'use strict';
// Review-only fixtures: no network, Android settings or production catalog writes.
const res = 'assets/';
const official = {vosh:'https://vserosolimp.edsoo.ru/iskusstvo', hse:'https://olymp.hse.ru/mmo/tasks-arthist'};
const scenarios = [
 ['Навигация','drawer','Боковое меню','Одобренное новое состояние: меню слева поверх затемнения. Закрытие крестиком, вне панели, свайпом влево или Escape/Назад. Главная уже реализована и не перепроектируется.'],
 ['Олимпиады','about','Об олимпиадах','Сохраняем три вкладки, блок новостей, исходную иллюстрацию и архив. Только две согласованные олимпиады. Регион не выбирается за пользователя.'],
 ['','news','Новость · подробности','Компактное закрываемое окно со сводкой, датой и явным переходом на официальный сайт. Длинный текст прокручивается внутри окна. Текст новости здесь условный.'],
 ['','materials','Учебные материалы','Выбор олимпиады ведёт на отдельную страницу фильтров. Этот и архивный вход используют один сценарий и одни фильтры.'],
 ['','filters','Фильтры материалов','Олимпиада, класс, учебный год и этап. Регион берётся из профиля, общие материалы доступны без региона. Набор вариантов в этом макете демонстрационный.'],
 ['','results','Результаты · несколько PDF','Каждый тур и тип документа — отдельная карточка. Названия и размеры условные; это не проверенный перечень опубликованных PDF.'],
 ['','materialempty','Материалов нет','Не подменяем отсутствие найденного документа утверждением, что он не существует. Оставляем фильтры и официальный архив.'],
 ['PDF','download','Загрузка · прогресс','Условный прогресс 42%, отмена и последующий выбор места сохранения. «Файл загружен» не означает «Файл сохранён».'],
 ['','downloaderror','Загрузка · ошибка','Обрыв связи либо недоступный файл. Есть повтор, архив и отмена. Реальная загрузка в прототипе не выполняется.'],
 ['','cancelled','Загрузка · отменена','Отмена не выдаётся за успешное сохранение. Можно начать заново.'],
 ['','save','Системное сохранение','Условная схема Android Documents UI, а не точная копия интерфейса конкретной модели. Успех появляется только после записи полного файла.'],
 ['','savecancel','Сохранение · отменено','Отмена выбора папки сохраняет возможность повторно выбрать место. Никакого сообщения об успешной записи.'],
 ['','saveerror','Сохранение · нет места','Ошибка записи отделена от ошибки сети. Предлагаем другое место, не ложный успех.'],
 ['','saved','PDF сохранён','Успех после записи; открытие внешним PDF-приложением. В этом макете файл не создаётся.'],
 ['','noviewer','Нет просмотрщика PDF','Сохранённый файл остаётся доступен пользователю, даже если нет приложения для открытия. Встроенного просмотрщика не добавляем.'],
 ['Регион и справка','guidance','Как выбрать…','Предлагаемый текст для отдельного согласования. Без неподтверждённых льгот, проходных баллов и обещаний поступления; ссылки на официальные архивы.'],
 ['','profile','Профиль · строка региона','Источник — обновлённый Figma 1:602 / 27:9657. Иконка карты, подпись «Регион» и значение справа. По согласованию длинное название переносится в правой колонке; под подпись его не переносим. Веб-страница показывает взаимодействия, точная вёрстка Android — из Figma.'],
 ['','region','Регион · поиск','Поиск и явное подтверждение выбора. Показаны три пилотные области и несколько примеров других регионов; это не полный справочник. Москва и Санкт-Петербург отделены от областей.'],
 ['','regionempty','Поиск · ничего не найдено','Показываем запрос и возможность очистки. Изменение поиска не стирает уже выбранный регион.'],
 ['','unsupported','Регион · неполное покрытие','Длинное название Чувашской Республики — пример для проверки переноса. Регион выбрать можно, но общие данные не выдаются за полный региональный календарь.'],
 ['','regionsaveerror','Регион · ошибка записи','Не сообщаем об успешной записи при ошибке. Предыдущий регион остаётся выбранным; можно повторить.'],
 ['Данные','refresh','Обновление · локальные данные','Неблокирующее обновление: новости и материалы остаются доступны. Дата редакционной проверки и время загрузки показаны раздельно.'],
 ['','refresherror','Обновление · ошибка','Сохраняется последняя хорошая копия; повтор доступен вручную. Переходы и смена месяца не запускают обновление.'],
 ['','offline','Первый запуск · без сети','Встроенный каталог доступен сразу. Сообщаем, что новых данных без сети нет; полный экран загрузки не нужен.'],
 ['Календарь','month','Месяц · сегодня и события','Реальная текущая дата берётся из браузера. Для проверки на сегодня назначены условные проведение и дедлайн: тёмная заливка имеет приоритет, пунктир сохраняется. Все события видны в дне.'],
 ['','month6','Месяц · шесть недель','Август 2026, понедельник первым. Пустые ячейки вне месяца не нажимаются. Нажатие даты сразу открывает день; возврат сохраняет исходный месяц.'],
 ['','day','День · события и время','Сохраняем недельную полосу, бегущие фигуры и карточки источника. Весь день, известное время с часовым поясом и дедлайн различимы. Нижней панели нет.'],
 ['','dayempty','День · нет событий','Нет известных событий в доступном каталоге — это не гарантия отсутствия олимпиады. Учитываем неполное региональное покрытие.'],
 ['','window','Неточная дата','Неопределённый период показан отдельно от подтверждённых дат. В календаре не закрашиваем весь период как дни проведения.']
];
const today = new Date(); today.setHours(12,0,0,0);
const state = {scenario:'about',page:'about',modal:null,history:[],text:'1',system:'1',width:'390',region:null,draftRegion:null,query:'',olympiad:'vosh',grade:'9',year:'2025/26',stage:'Региональный',month:new Date(today.getFullYear(),today.getMonth(),1,12),date:new Date(today),origin:'month',data:'ready',download:'download'};
const phone=document.querySelector('#phone'),screen=document.querySelector('#screen');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const image=(name,cls='',alt='')=>`<img class="${cls}" src="${res}figma_${name}.png" alt="${alt}">`;
const button=(label,action,cls='primary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const external=(label,url)=>`<a class="text-link" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const dateText=d=>d.toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});
const monthText=d=>d.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});
const regionName=()=>state.region||'Регион не выбран';
const supported=()=>['Московская область','Ленинградская область','Владимирская область'].includes(state.region);
const source=()=>official[state.olympiad];
function title(){return {home:'Καλωσόρισμα',profile:'Профиль',about:'Олимпиады',materials:'Олимпиады',guidance:'Олимпиады',filters:'Учебные материалы',results:'Материалы',materialempty:'Материалы',month:'Календарь',day:'Расписание',dayempty:'Расписание',window:'Календарь'}[state.page]||'Олимпиады';}
function header(){return `<header class="app-header">${button(state.page==='home'?image('home_menu'):image('back'),'headerback','icon-button',`aria-label="${state.page==='home'?'Открыть меню':'Назад'}"`)}<h2 class="${state.page==='home'?'home-heading':''}">${esc(title())}</h2>${['about','materials','guidance'].includes(state.page)?button(image('home_menu'),'drawer','icon-button','aria-label="Открыть меню"'):'<span></span>'}</header>`;}
function bottom(){if(['day','dayempty'].includes(state.page))return '';return `<nav class="nav-bottom" aria-label="Основная навигация">${[['home','Дом','nav_home'],['month','Календарь','nav_calendar'],['lessons','Уроки','nav_lessons_glyph'],['chat','Чат','nav_chat_glyph'],['profile','Профиль','profile_person']].map(([page,label,asset])=>`<button type="button" data-action="nav:${page}" ${page==='lessons'||page==='chat'?'disabled aria-label="'+label+' — недоступно"':''} ${state.page===page?'aria-current="page"':''}>${['lessons','chat','profile'].includes(page)?`<span class="nav-disc">${image(asset)}</span>`:image(asset)}<span>${label}</span></button>`).join('')}</nav>`;}
function tabs(){return `<div class="tabs" role="tablist" aria-label="Разделы олимпиад">${[['about','Об олимпиадах'],['materials','Учебные материалы'],['guidance','Как выбрать']].map(([page,label])=>button(label,'tab:'+page,'',`role="tab" aria-selected="${state.page===page}"`)).join('')}</div>`;}
function regionContext(){return `<div class="region-context">${esc(regionName())} · ${button('Изменить','region','text-link')}</div>${!state.region?`<div class="notice">Пока показываем общие сведения. Выберите регион, чтобы видеть доступные местные даты.${button('Выбрать регион','region','text-link')}</div>`:!supported()?'<div class="notice">Региональные сведения пока неполные. Доступны общие события и материалы. Отсутствие даты не означает, что события нет.</div>':''}`;}
function dataStatus(){let msg='';if(state.data==='refresh')msg='Обновляем каталог… Сохранённые сведения доступны.';if(state.data==='error')msg='Не удалось обновить каталог. Показываем сохранённую версию.';if(state.data==='offline')msg='Нет сети. Доступен встроенный каталог; новые сведения пока не загружены.';return `${msg?`<div class="notice ${state.data==='error'?'error':''}" role="status">${msg}${state.data!=='refresh'?button('Повторить обновление','refresh','text-link'):''}</div>`:''}<small>Проверено редакцией: 28.10.2026<br>${state.data==='offline'?'Версия из приложения':'Загружено: 29.10.2026, 18:40'}</small>${button(state.data==='refresh'?'Показать результат обновления':'Обновить','refresh','text-link')}`;}
function newsCard(long=false){return `<div class="white-card"><strong>Опубликованы материалы прошлого сезона</strong><p>${long?'В архив добавлены задания и критерии оценивания. Сверьте учебный год, этап и класс на официальном сайте. Условия нового сезона могут отличаться.':'Задания и критерии доступны в официальном архиве.'}</p><small>28 октября 2026 · официальный архив</small></div>`;}
function about(){return `${tabs()}${regionContext()}<section class="panel figma-news-panel"><div class="panel-title">♧ Новости</div>${button('<span><strong>Опубликованы материалы прошлого сезона</strong><small>28 октября · задания и критерии</small></span><span class="chevron">›</span>','news','white-card card-button')}${button('<span><strong>Как проверить сроки своего этапа</strong><small>Сверьте сведения организатора своего региона</small></span><span class="chevron">›</span>','news','white-card card-button')}</section><img class="art olympiads-art" src="assets/olympiads-art.png" alt="Античные фигуры из исходного Design"><section class="panel figma-archive-panel"><div class="panel-title">▱ Материалы прошлых лет</div>${olympiadCards()}</section>${dataStatus()}`;}
function olympiadCards(){return [['vosh','ВсОШ по искусству (МХК)','Школьный, муниципальный, региональный и заключительный этапы'],['hse','«Высшая проба»','История искусств']].map(([id,label,sub])=>button(`<span><strong>${label}</strong><small>${sub}</small></span><span class="chevron">›</span>`,'choose:'+id,'white-card card-button')).join('');}
function materials(){return `${tabs()}${regionContext()}<h3>Выберите олимпиаду</h3><p class="subtle">Задания, ответы и критерии прошлых лет</p><section class="panel">${olympiadCards()}</section><div class="notice">Учебные годы: 2024/25 и 2025/26. Наличие документов зависит от класса, этапа и территории.</div>`;}
function selectField(key,label,values,current){return `<div class="form-field"><label for="filter-${key}">${label}</label><select id="filter-${key}" data-filter="${key}">${values.map(([value,text])=>`<option value="${value}" ${value===current?'selected':''}>${text}</option>`).join('')}</select></div>`;}
function filters(){return `${regionContext()}${selectField('olympiad','Олимпиада',[['vosh','ВсОШ · искусство (МХК)'],['hse','Высшая проба · история искусств']],state.olympiad)}${selectField('grade','Класс',Array.from({length:7},(_,i)=>[String(i+5),String(i+5)]),state.grade)}${selectField('year','Учебный год',[['2025/26','2025/26'],['2024/25','2024/25']],state.year)}${selectField('stage','Этап',(state.olympiad==='vosh'?['Школьный','Муниципальный','Региональный','Заключительный']:['Отборочный','Заключительный']).map(s=>[s,s]),state.stage)}${button('Показать материалы','results')}<small style="margin-top:14px">Если подходящего документа нет, покажем причину и ссылку на официальный архив.</small>`;}
function filterSummary(){return `<div class="notice"><strong>${state.olympiad==='vosh'?'ВсОШ · искусство (МХК)':'Высшая проба · история искусств'}</strong><br>${esc(state.grade)} класс · ${esc(state.year)} · ${esc(state.stage)} этап<br>${esc(regionName())}${button('Изменить фильтры','filters','text-link')}</div>`;}
function results(empty=false){return `${filterSummary()}${empty?`<div class="empty"><h3>Подходящих файлов пока нет</h3><p>Для этого сочетания в каталоге не найден проверенный PDF. Он мог ещё не быть опубликован или быть доступен в другом формате.</p>${external('Проверить официальный архив',source())}${button('Изменить фильтры','filters','secondary')}</div>`:`<h3>Документы · 4 файла</h3>${['Тур 1 · задания','Тур 1 · ответы и критерии','Тур 2 · задания','Тур 2 · ответы и критерии'].map((t,i)=>`<article class="white-card file-card"><div class="file-kind">${i%2?'ОТВЕТЫ И КРИТЕРИИ':'ЗАДАНИЯ'} · PDF</div><strong>${t}</strong><small>${esc(state.grade)} класс · ${esc(state.year)}<br>${esc(state.stage)} этап · ${state.olympiad==='hse'?'Общие материалы':esc(regionName())}<br>Официальный архив · пример 2,4 МБ</small>${button('Скачать PDF','download','secondary')}</article>`).join('')}${external('Официальный архив',source())}${button('Посмотреть отсутствие файлов','emptyresults','text-link')}`}`;}
function guidance(){return `${tabs()}<div class="guidance"><h3>С чего начать</h3><p>Выберите олимпиаду по интересу к искусству и истории культуры. Сначала проверьте правила участия, затем посмотрите задания прошлых лет.</p><h3>Проверьте условия</h3><ol><li>Найдите на официальном сайте свой класс и нужный этап.</li><li>Сверьте даты у организатора. Местные сроки могут отличаться.</li><li>Разделяйте задания и критерии: попробуйте решить самостоятельно, затем сравните.</li></ol><h3>Два направления</h3><p><strong>ВсОШ по искусству (МХК).</strong> Материалы сгруппированы по учебным годам и этапам.</p>${external('Архив ВсОШ',official.vosh)}<p><strong>«Высшая проба»: история искусств.</strong> Смотрите задания и решения на сайте организатора.</p>${external('Архив «Высшей пробы»',official.hse)}<div class="notice">Точные условия текущего сезона проверяйте на официальном сайте. Материалы прошлых лет помогают познакомиться с форматом.</div></div>`;}
function profileRow(label,icon,value='',action=''){return `<${action?'button':'div'} class="profile-row" ${action?`type="button" data-action="${action}"`:''}>${image(icon)}<span>${label}</span>${value?`<small>${value}</small>`:''}<span aria-hidden="true" style="flex:0">${action?'›':'·'}</span></${action?'button':'div'}>`;}
function profile(){return `<div class="profile-group profile-identity"><div class="avatar">${image('profile_person')}</div><div><strong>Алексей Примеров</strong><small>demo@example.com · демо</small></div></div><h3>Аккаунт</h3><div class="profile-group">${profileRow('Изменить профиль','profile_person')}${profileRow('Уведомления','profile_notifications')}${profileRow('Язык','profile_language','Русский')}<button class="profile-row region-row" data-action="region"><span class="region-map-circle"><img src="assets/region-map.svg" alt=""></span><span class="region-label">Регион</span><small class="region-value">${esc(state.region||'Не выбран')}</small><b aria-hidden="true">›</b></button></div><h3>Внешний вид</h3><div class="profile-group">${profileRow('Размер текста','profile_text',{'1':'Системный','1.15':'Средний','1.3':'Большой'}[state.text],'textmodal')}${profileRow('Тема','profile_theme','Светлая')}</div><h3>Безопасность</h3><div class="profile-group">${profileRow('Чат поддержки','profile_help')}${profileRow('Пароль','profile_password')}${profileRow('Face ID','profile_biometric','<i class="toggle"></i>')}</div>${state.scenario==='regionsaveerror'?'<div class="notice error">Не удалось сохранить регион. Предыдущее значение оставлено.</div>':''}`;}
function fixture(d){const n=d.getDate();if(d.getFullYear()===today.getFullYear()&&d.getMonth()===today.getMonth()&&n===today.getDate())return 'dark';return [7,16,17,18].includes(n)?'dark':[3,9,12,22].includes(n)?'light':'';}
function calendar(mini=false){let y=state.month.getFullYear(),m=state.month.getMonth(),offset=(new Date(y,m,1,12).getDay()+6)%7,days=new Date(y,m+1,0,12).getDate(),cells=Math.ceil((offset+days)/7)*7;let current=y===today.getFullYear()&&m===today.getMonth();return `<div class="${mini?'mini-calendar':'full-calendar'}"><div class="calendar-head">${button(`<span class="month-title">${esc(current?dateText(today):monthText(state.month))}</span>`,mini?'openmonth':'currentmonth','calendar-title','aria-label="Открыть месяц: '+esc(monthText(state.month))+'"')}${button('‹','prevmonth','icon-button','aria-label="Предыдущий месяц"')}${button('›','nextmonth','icon-button','aria-label="Следующий месяц"')}</div><div class="calendar-grid" data-rows="${cells/7}">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:cells},(_,i)=>{let n=i-offset+1;if(n<1||n>days)return '<span class="day-cell" aria-hidden="true"></span>';let d=new Date(y,m,n,12),kind=fixture(d),isToday=d.toDateString()===today.toDateString();return button(`<span class="day-circle ${kind} ${isToday?'today':''}">${n}</span>`,'date:'+n,'day-cell',`aria-label="${esc(dateText(d))}${isToday?', сегодня':''}${kind==='dark'?', проведение олимпиады':kind?', событие или дедлайн':', нет известных событий'}"`);}).join('')}</div></div>`;}
const legend=()=>'<div class="calendar-legend"><span><i class="dot"></i>Нет событий</span><span><i class="dot light"></i>Событие / срок</span><span><i class="dot dark"></i>Проведение</span><span><i class="dot today"></i>Сегодня</span></div>';
function home(){return `<div class="notice"><h3>Главная уже реализована</h3><p>Её принятый дизайн сохраняется. Новое состояние в этом наборе — только боковое меню.</p>${button('Открыть боковое меню','drawer','secondary')}${external('Исходная Главная в Figma','https://www.figma.com/design/gO7czKDJEPs8z3aG2YPlAE?node-id=1-7859')}</div>`;}
function eventCards(){const kind=fixture(state.date),overlap=state.date.toDateString()===today.toDateString();if(!kind)return '<div class="empty">В доступном каталоге нет подтверждённых событий на эту дату.</div>';return `${kind==='dark'?`<article class="event-card conduct"><small>Проведение олимпиады</small><div class="event-time">Весь день · ${esc(dateText(state.date))}</div><strong>ВсОШ по искусству (МХК)</strong><p>Региональный этап · ${state.region&&supported()?esc(state.region):'общие сведения'}</p>${external('Официальный источник',official.vosh)}</article>`:''}${kind==='light'||overlap?`<article class="event-card"><small>Регистрация · последний день</small><div class="event-time">До 18:00 · МСК (UTC+3)</div><strong>«Высшая проба» · история искусств</strong><p>Время показано только при наличии в источнике.</p>${external('Официальный источник',official.hse)}</article>`:''}`;}
function month(){return `${calendar()}${legend()}<div class="monthly-list"><h3>События на ${esc(dateText(state.date))}</h3>${eventCards()}${button('Период без точной даты','window','text-link')}</div><small>Регион: ${esc(regionName())}</small>`;}
function week(){const monday=new Date(state.date);monday.setDate(monday.getDate()-(monday.getDay()+6)%7);return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);return button(`<small>${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][i]}</small><strong>${d.getDate()}</strong>`,'week:'+i,d.toDateString()===state.date.toDateString()?'selected':'',`aria-label="${esc(dateText(d))}"`);}).join('')}</div>`;}
function day(empty=false){return `<div class="calendar-head">${button(esc(dateText(state.date)),'daymonth','calendar-title','aria-label="Вернуться к месяцу"')}</div>${week()}<img class="art daily-art" src="assets/daily-art.png" alt="Бегущие античные фигуры из исходного Design">${empty?`<div class="empty"><h3>На этот день событий пока нет</h3><p>В доступном каталоге нет подтверждённых событий на эту дату.</p><p class="subtle">Региональные данные могут быть неполными.</p>${button('Открыть месяц','daymonth','secondary')}</div>`:eventCards()}`;}
function windowPage(){return `<h3>Срок уточняется</h3><article class="event-card"><small>Предварительный период</small><strong>Ноябрь 2026</strong><p>Точный день и время пока не подтверждены. Период не отмечен в сетке как дни проведения.</p>${external('Уточнить у организатора',official.vosh)}</article>${button('Вернуться в календарь','nav:month','secondary')}`;}
const regions=['Московская область','Ленинградская область','Владимирская область','Москва','Санкт-Петербург','Чувашская Республика — Чувашия','Республика Саха (Якутия)'];
function regionOptions(){const q=state.query.trim().toLocaleLowerCase('ru');const items=regions.filter(r=>r.toLocaleLowerCase('ru').includes(q));return `${items.length?items.map(r=>button(`<span>${esc(r)}<small>${regions.indexOf(r)<3?'Пилотное покрытие':'Региональные сведения пока неполные'}</small></span><b>${state.draftRegion===r?'●':'○'}</b>`,'pickregion:'+r,'region-option',`aria-pressed="${state.draftRegion===r}"`)).join(''):`<p class="empty">По запросу «${esc(state.query)}» ничего не найдено.</p>${button('Очистить поиск','clearsearch','secondary')}`}`;}
function regionModal(){return `<h2>Выберите регион</h2><input class="region-search" id="region-search" type="search" placeholder="Поиск региона" aria-label="Поиск региона" value="${esc(state.query)}"><div id="region-results">${regionOptions()}</div><small style="margin-top:14px">Области и города Москва и Санкт-Петербург — разные территории.</small>${button('Без региона · только общие данные','noregion','text-link')}<div id="region-feedback">${state.scenario==='regionsaveerror'?'<div class="notice error">Не удалось записать выбор. Предыдущий регион не изменён.</div>':''}</div>${button('Сохранить выбор','saveregion','primary',state.draftRegion?'':'disabled')}`;}
function downloadBody(){const t=state.download;let body='';if(t==='download')body='<p>Тур 1 · задания · PDF</p><div class="progress" role="progressbar" aria-valuenow="42" aria-valuemin="0" aria-valuemax="100" aria-label="Загрузка PDF"><i></i></div><p><strong>42%</strong> · 1,0 из 2,4 МБ</p><small>После загрузки выберите, куда сохранить файл.</small>'+button('Отменить загрузку','cancelpdf','secondary')+button('Показать завершение загрузки','downloaded','text-link');
 else if(t==='downloaderror')body='<div class="notice error">Загрузка прервана. Проверьте сеть или доступность файла у организатора.</div>'+button('Повторить','download')+external('Открыть официальный архив',source())+button('Отмена','close','secondary');
 else if(t==='cancelled')body='<p>Загрузка отменена. Файл не сохранён.</p>'+button('Загрузить заново','download')+button('Закрыть','close','secondary');
 else if(t==='save')body='<div class="notice">Файл получен. Выберите место для сохранения.</div><div class="white-card system-sheet"><small>Системное окно Android · схема</small><h3>Сохранить в «Загрузки»</h3><label for="filename">Имя файла</label><input id="filename" value="vosh-art-tasks.pdf" readonly>'+button('Сохранить','saved')+button('Отмена','savecancel','secondary')+'</div>';
 else if(t==='savecancel')body='<p>Сохранение отменено. Файл ещё не записан в выбранную папку.</p>'+button('Выбрать место снова','downloaded')+button('Закрыть','close','secondary');
 else if(t==='saveerror')body='<div class="notice error">Не удалось записать файл: недостаточно места. Файл не сохранён.</div>'+button('Выбрать другое место','downloaded')+button('Закрыть','close','secondary');
 else if(t==='saved')body='<div class="notice success"><strong>PDF сохранён</strong><p>vosh-art-tasks.pdf<br>Загрузки · 2,4 МБ</p></div>'+button('Открыть PDF','openpdf')+button('Готово','close','secondary');
 else if(t==='noviewer')body='<p>PDF сохранён, но приложение для его открытия не найдено.</p><small>Вы можете открыть vosh-art-tasks.pdf позже через приложение «Файлы».</small>'+button('Понятно','close');return `<h2>${['saved','noviewer'].includes(t)?'Документ':'Загрузка PDF'}</h2>${body}`;}
function overlay(){if(!state.modal)return '';let content='',cls='';if(state.modal==='drawer'){cls='drawer';content=`<div class="modal-head"><h2>Меню</h2>${button('×','close','icon-button','aria-label="Закрыть меню"')}</div><div class="drawer-items">${button('Дом','nav:home','')}${button('Олимпиады','nav:about',['about','materials','guidance'].includes(state.page)?'active':'')}${button('Календарь','nav:month','')}${button('Вводный курс <span class="pill">Скоро</span>','noop','','disabled')}${button('Курсы <span class="pill">Скоро</span>','noop','','disabled')}${button('Профиль','nav:profile','')}</div><footer>Искусство и культура<br>Anavasi</footer>`;}
 else if(state.modal==='news')content=`<h2>Материалы прошлого сезона</h2><small style="margin-top:12px">28 октября 2026 · официальный архив</small><p style="margin-top:18px">В архив добавлены задания и критерии оценивания. Выберите учебный год, этап и класс. Сверьте условия текущего сезона отдельно: архивные документы не заменяют актуальные правила.</p><p>Задания и ответы представлены отдельно, чтобы можно было сначала попробовать свои силы.</p><small>Источник: Центр олимпиадного движения</small><a class="primary" href="${official.vosh}" target="_blank" rel="noopener noreferrer">Открыть источник ↗</a><small style="margin-top:10px">Откроется внешний браузер.</small>`;
 else if(state.modal==='region')content=regionModal();else if(state.modal==='pdf')content=downloadBody();else if(state.modal==='text')content='<h2>Размер текста</h2>'+[['1','Системный'],['1.15','Средний'],['1.3','Большой']].map(([v,t])=>button(`${t} ${state.text===v?'●':'○'}`,'text:'+v,'region-option')).join('');
 return `<div class="modal-layer ${cls?'drawer-layer':''}" data-dismiss="true"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${state.modal==='drawer'?'Меню':state.modal==='region'?'Выбор региона':state.modal==='news'?'Новость':state.modal==='text'?'Размер текста':'PDF'}">${cls?'':`<div style="display:flex;justify-content:flex-end">${button('×','close','icon-button','aria-label="Закрыть окно"')}</div>`}${content}</section></div>`;}
function body(){switch(state.page){case'home':return home();case'about':return about();case'materials':return materials();case'filters':return filters();case'results':return results();case'materialempty':return results(true);case'guidance':return guidance();case'profile':return profile();case'month':return month();case'day':return day();case'dayempty':return day(true);case'window':return windowPage();default:return about();}}
function fitFixedPage(){phone.style.setProperty('--actual-system',state.system);phone.style.setProperty('--fit','1');if(!['home','profile'].includes(state.page))return;/* Review approximation: reserve a fixed text budget for the largest preset. Compose retains its actual per-label fitter. */phone.style.setProperty('--system','1');phone.style.setProperty('--fit','.96');}
function render(focus=true){const old=screen.querySelector('.app-main')?.scrollTop||0;screen.innerHTML=header()+`<div class="app-main ${state.page==='profile'?'profile-main':''} ${state.page==='home'?'home-main':''}">${body()}</div>`+bottom()+overlay();phone.style.setProperty('--text',state.text);phone.style.setProperty('--system',state.system);phone.style.width=state.width+'px';document.querySelector('#text').value=state.text;document.querySelector('#system').value=state.system;document.querySelector('#width').value=state.width;fitFixedPage();screen.querySelector('.app-main').scrollTop=old;screen.querySelector('.app-main').inert=Boolean(state.modal);screen.querySelector('.app-header').inert=Boolean(state.modal);if(screen.querySelector('.nav-bottom'))screen.querySelector('.nav-bottom').inert=Boolean(state.modal);if(focus&&state.modal)screen.querySelector('.modal button,.modal input')?.focus({preventScroll:true});document.querySelector('#review-warning').textContent=['home','profile'].includes(state.page)?'Главная и Профиль: в макете размер подбирается с запасом под «Большой». Это приближение принятого Android-рендерера; точные размеры и области нажатия проверяются в Compose.':'';updateReview();}
function updateReview(){const s=scenarios.find(s=>s[1]===state.scenario);document.querySelector('#scenario-title').textContent=s?.[2]||title();document.querySelector('#scenario-note').textContent=s?.[3]||'';document.querySelectorAll('.scenario-link').forEach(b=>b.setAttribute('aria-current',String(b.dataset.scenario===state.scenario)));if(state.page==='profile')document.querySelector('#review-warning').textContent='Профиль: точная вёрстка Android берётся из Figma 1:602 / 27:9657. Здесь показаны работа строки региона и согласованный перенос справа.';if(state.page==='home')document.querySelector('#review-warning').textContent='Главная не изменяется. Здесь только служебная отметка прототипа и вход в новое меню.';}
function push(){state.history.push({page:state.page,modal:state.modal,month:new Date(state.month),date:new Date(state.date),scenario:state.scenario});}
function go(page,scenario=page){if(state.page!==page||state.modal)push();state.page=page;state.scenario=scenario;state.modal=null;render();screen.querySelector('.app-main').scrollTop=0;}
function back(){if(state.modal){state.modal=null;render();return;}const prev=state.history.pop();if(prev)Object.assign(state,prev);else{state.page='home';state.scenario='home';}render();}
function openModal(which,scenario=which){state.modal=which;state.scenario=scenario;render();}
function setScenario(id){state.scenario=id;state.modal=null;state.query='';state.data='ready';state.history=[];state.month=new Date(today.getFullYear(),today.getMonth(),1,12);state.date=new Date(today);if(['home','home6'].includes(id)){state.page='home';if(id==='home6')state.month=new Date(2026,7,1,12);}else if(id==='drawer'){state.page='about';state.modal='drawer';}else if(id==='news'){state.page='about';state.modal='news';}else if(['download','downloaderror','cancelled','save','savecancel','saveerror','saved','noviewer'].includes(id)){state.page='results';state.modal='pdf';state.download=id;}else if(['region','regionempty','regionsaveerror'].includes(id)){state.page='profile';state.modal='region';state.draftRegion=state.region;state.query=id==='regionempty'?'Несуществующий регион':'';}else if(id==='unsupported'){state.page='profile';state.region='Чувашская Республика — Чувашия';}else if(['refresh','refresherror','offline'].includes(id)){state.page='about';state.data={refresh:'refresh',refresherror:'error',offline:'offline'}[id];}else if(id==='month6'){state.page='month';state.month=new Date(2026,7,1,12);state.date=new Date(2026,7,16,12);}else state.page=id;render();screen.querySelector('.app-main').scrollTop=0;history.replaceState(null,'','#'+id);}
document.querySelector('#scenarios').innerHTML=scenarios.map(([group,id,label])=>`${group?`<h3>${group}</h3>`:''}<button class="scenario-link" type="button" data-scenario="${id}">${label}</button>`).join('');
document.querySelector('#scenarios').addEventListener('click',e=>{const b=e.target.closest('[data-scenario]');if(b){setScenario(b.dataset.scenario);document.querySelector('.preview').scrollIntoView({block:'start'});}});
for(const id of ['text','width','system'])document.querySelector('#'+id).addEventListener('change',e=>{state[id]=e.target.value;render(false);});
document.querySelector('#back').addEventListener('click',back);
document.querySelector('#reset').addEventListener('click',()=>{state.region=null;state.text='1';state.system='1';state.width='390';state.olympiad='vosh';state.grade='9';state.year='2025/26';state.stage='Региональный';setScenario('about');});
screen.addEventListener('change',e=>{if(e.target.dataset.filter){state[e.target.dataset.filter]=e.target.value;if(e.target.dataset.filter==='olympiad')state.stage=state.olympiad==='vosh'?'Региональный':'Отборочный';render(false);}});
screen.addEventListener('input',e=>{if(e.target.id==='region-search'){state.query=e.target.value;document.querySelector('#region-results').innerHTML=regionOptions();}});
screen.addEventListener('click',e=>{if(e.target.classList.contains('modal-layer')){state.modal=null;render();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const [a,...parts]=b.dataset.action.split(':'),value=parts.join(':');
 switch(a){case'noop':return;case'close':state.modal=null;break;case'headerback':if(state.page==='home'){openModal('drawer');return;}back();return;case'drawer':openModal('drawer');return;case'nav':go(value);return;case'tab':go(value);return;case'choose':state.olympiad=value;state.stage=value==='vosh'?'Региональный':'Отборочный';go('filters');return;case'filters':go('filters');return;case'results':go('results');return;case'emptyresults':go('materialempty');return;case'news':openModal('news');return;case'region':state.draftRegion=state.region;state.query='';openModal('region');return;case'pickregion':state.draftRegion=value;render(false);return;case'clearsearch':state.query='';render(false);screen.querySelector('#region-search').focus();return;case'noregion':state.draftRegion=null;state.region=null;state.modal=null;break;case'saveregion':if(state.scenario==='regionsaveerror'){document.querySelector('#region-feedback').innerHTML='<div class="notice error">Не удалось записать выбор. Предыдущий регион не изменён. <button class="text-link" data-action="retryregion">Повторить</button></div>';return;}state.region=state.draftRegion;state.modal=null;break;case'retryregion':state.region=state.draftRegion;state.modal=null;state.scenario='profile';break;case'textmodal':openModal('text','profile');return;case'text':state.text=value;state.modal=null;break;case'prevmonth':state.month=new Date(state.month.getFullYear(),state.month.getMonth()-1,1,12);state.date=new Date(state.month);break;case'nextmonth':state.month=new Date(state.month.getFullYear(),state.month.getMonth()+1,1,12);state.date=new Date(state.month);break;case'currentmonth':state.month=new Date(today.getFullYear(),today.getMonth(),1,12);state.date=new Date(today);break;case'openmonth':state.origin='home';go('month');return;case'date':push();state.origin=state.page;state.date=new Date(state.month.getFullYear(),state.month.getMonth(),Number(value),12);state.page=fixture(state.date)?'day':'dayempty';state.scenario=state.page;render();return;case'week':{const d=new Date(state.date);d.setDate(d.getDate()-(d.getDay()+6)%7+Number(value));state.date=d;state.page=fixture(d)?'day':'dayempty';state.scenario=state.page;break;}case'daymonth':state.month=new Date(state.date.getFullYear(),state.date.getMonth(),1,12);go('month');return;case'window':go('window');return;case'refresh':if(state.data==='refresh'){state.data='ready';state.scenario='about';}else{state.data='refresh';state.scenario='refresh';}break;case'download':state.download='download';openModal('pdf','download');return;case'cancelpdf':state.download='cancelled';state.scenario='cancelled';break;case'downloaded':state.download='save';state.scenario='save';break;case'savecancel':state.download='savecancel';state.scenario='savecancel';break;case'saved':state.download='saved';state.scenario='saved';break;case'openpdf':state.download='noviewer';state.scenario='noviewer';break;
 }render(false);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();back();}if(e.key==='Tab'&&state.modal){const controls=[...screen.querySelectorAll('.modal button:not(:disabled),.modal input,.modal a[href],.modal select')];if(!controls.length)return;const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
let pointerStart=null;screen.addEventListener('pointerdown',e=>{if(state.modal==='drawer')pointerStart={x:e.clientX,y:e.clientY};});screen.addEventListener('pointerup',e=>{if(pointerStart&&state.modal==='drawer'&&e.clientX-pointerStart.x< -60&&Math.abs(e.clientY-pointerStart.y)<60){state.modal=null;render();}pointerStart=null;});
const initial=location.hash.slice(1);setScenario(scenarios.some(s=>s[1]===initial)?initial:'about');
